head.script:
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_Search);
        // 목록 조회
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05100.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurNm_onkeypress
 * @description txb_IsurNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurNm_onkeypress = function() {
    try {
        if (window.event.keyCode === 13) scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.txb_IsurNm_onkeypress" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        scwin.showIsur(txb_IsurNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        if (row > 0) {
            scwin.fn_GetPar = scwin.getParIsuDelInfo;
            $c.bns.fn_PopIsuDetail(lbl_IsurNm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDBNS05100.xml', SCREN_PROCS_TP_CD_07, '');
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_일괄상장 매출액 미통보 종목.xls";
        $c.data.downloadGridViewExcel(grd_List, {fileName: "일괄상장 매출액 미통보", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05100.btn_ToExcel_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 일괄상장매출액미통보 내역 조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    const dsNm = 'BNS_PACK_UN_SALES_LIST';
    const qryId = 'lds.stf.bnspack.select.listSalesNonNoti';
    const param = '&{P}V_ISUR_CD=' + txb_IsurNm.getValue();
    $c.bns.fn_SearchBns('ULDBNS05100.xml', dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurNm.setValue(arrPar[0].ISUR_NM);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {String} txb_IsurNm txb_IsurNm
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(txb_IsurNm) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(lbl_IsurNm);
};

/**
 * @method
 * @name getParIsuDelInfo
 * @description 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};
